 for(const f of F[role]){const v=d[f.k];if(v===null||v===undefined||v==='')continue;if(f.type==='number'&&(!Number.isFinite(Number(v))||Array.isArray(v)))return f.label+' must be a scalar number.';if(f.type==='date'&&!okDate(v))return f.label+' must be a valid date.';if(f.type==='select'&&!f.arg.includes(v))return f.label+' has an invalid value.';if(f.type==='boolean'&&!['true','false',true,false].includes(v))return f.label+' must be Yes/No.';if(f.type==='ref'&&(!s(v)||!byId(f.arg,v)))return f.label+' must reference an authorized existing record.';if(['website','sourceUrl'].includes(f.k)&&s(v)&&!urlOk(v))return f.label+' must use an HTTPS URL.';}
