 if(role==='projects'){if(!old&&d.status!=='Draft')return 'Create the RFP in Draft, then build and review its criteria.';if(d.status==='Awarded'&&old?.data.status!=='Awarded'&&!records('awards').some(x=>x.data.projectId===old?.id&&x.data.status==='Approved'))return 'Use an approved award decision before marking an RFP Awarded.';if(['Issued','Collecting','Evaluating'].includes(d.status)&&!okDate(d.responseDue))return 'Open RFPs require a dated bid deadline.';if(d.responseDue&&d.decisionDue&&d.decisionDue<d.responseDue)return 'Decision target cannot precede bid deadline.';if(['Issued','Collecting','Evaluating'].includes(d.status)&&old?.data.status==='Draft'&&(!records('requirements').some(r=>r.data.projectId===old.id)||Math.abs(records('requirements').filter(r=>r.data.projectId===old.id).reduce((a,r)=>a+Number(r.data.weight||0),0)-100)>0.01))return 'Issuing this RFP requires its approved weighted criteria to total 100%.';if(old&&['Issued','Collecting','Evaluating','Awarded'].includes(old.data.status)&&['scope','responseDue','issuedAt'].some(k=>s(d[k])!==s(old.data[k])))return 'Issued scope and dates are preserved; create a reviewed new RFP revision instead of overwriting history.';}
 if(role==='providers'){const clash=records('providers').some(x=>x.id!==old?.id&&(s(x.data.name).toLowerCase()===s(d.name).toLowerCase()||(!!s(x.data.website)&&!!s(d.website)&&s(x.data.website).toLowerCase()===s(d.website).toLowerCase())));if(clash)return 'Provider organization already exists. Link the existing CRO across RFPs.';}
 if(role==='invitations'){if(records('invitations').some(x=>x.id!==old?.id&&x.data.projectId===d.projectId&&x.data.providerId===d.providerId))return 'This provider is already invited to the RFP.';if(d.status==='Received'&&!okDate(d.receivedAt))return 'Received bids require a verified receipt date.';if(old&&old.data.status==='Received'&&['status','receivedAt','projectId','providerId'].some(k=>s(d[k])!==s(old.data[k])))return 'Received bids are historical evidence. Record a new revision, not an overwrite.';}
