 if(role==='reviews'){const inv=byId('invitations',d.invitationId),q=byId('requirements',d.requirementId);if(!inv||!q||inv.data.projectId!==q.data.projectId)return 'Review must reference a CRO and requirement from the same RFP.';if(records('reviews').some(x=>x.id!==old?.id&&x.data.invitationId===d.invitationId&&x.data.requirementId===d.requirementId&&s(x.data.reviewer).toLowerCase()===s(d.reviewer).toLowerCase()))return 'This reviewer already scored the same CRO and criterion.';if(!(Number(d.score)>=1&&Number(d.score)<=5))return 'Score must be between 1 and 5.';if(d.status==='Reviewed'&&(!s(d.rationale)||!okDate(d.reviewedAt)))return 'Reviewed scores require a dated evidence-based rationale.';if(old&&old.data.status==='Reviewed'&&['score','reviewer','rationale','requirementId','invitationId'].some(k=>s(d[k])!==s(old.data[k])))return 'Return this reviewed score to Draft before revising its evidence.';}
