 if(!ready(allRoles))return 'Source records are incomplete.';
 const cov=vendorCoverage(inv),score=scoreFor(inv);if(cov.mandatoryMissing.length||cov.duplicate||score.score===null)return 'Cannot approve award while mandatory response or reviewed scoring evidence is incomplete.';
 if(records('clarifications').some(x=>x.data.invitationId===inv.id&&x.data.status==='Open'))return 'Close or resolve outstanding CRO clarifications before approval.';
